<?php
namespace App\Domain\AI\Knowledge\Services;use App\Domain\AI\Agents\Enums\AgentVersionStatus;use App\Domain\AI\Agents\Models\{Agent,AgentVersion};use App\Domain\AI\Agents\Services\AiLifecycleAuthorization;use App\Domain\AI\Knowledge\Enums\{KnowledgeSourceStatus,KnowledgeVersionStatus};use App\Domain\AI\Knowledge\Exceptions\{ArchivedKnowledgeSourceException,KnowledgeAttachmentConflictException};use App\Domain\AI\Knowledge\Models\{AgentVersionKnowledgeSource,KnowledgeSource,KnowledgeSourceVersion};use App\Domain\AI\Knowledge\Support\KnowledgeConstraintClassifier;use App\Domain\AI\Tenancy\AiTenantBoundary;use App\Models\User;use Illuminate\Database\QueryException;use Illuminate\Support\Facades\DB;
final class AttachKnowledgeToAgentVersionService{public function __construct(private AiLifecycleAuthorization$auth,private AiTenantBoundary$tenants){}public function attach(User$actor,Agent$agent,KnowledgeSourceVersion$knowledge):AgentVersionKnowledgeSource{try{return DB::transaction(function()use($actor,$agent,$knowledge){$a=$this->auth->authorize($actor);$tenantId=$this->tenants->requireTenantId();$version=AgentVersion::query()->where('agent_id',$agent->id)->where('status',AgentVersionStatus::Draft->value)->lockForUpdate()->latest('version_number')->firstOrFail();$source=KnowledgeSource::query()->lockForUpdate()->findOrFail($knowledge->knowledge_source_id);if($source->status!==KnowledgeSourceStatus::Active)throw new ArchivedKnowledgeSourceException('Archived knowledge cannot be attached.');$kv=KnowledgeSourceVersion::query()->lockForUpdate()->findOrFail($knowledge->id);if((int)$kv->knowledge_source_id!==(int)$source->id||(int)$kv->tenant_id!==$tenantId)throw new \DomainException('Knowledge attachment structure is invalid.');if($kv->status!==KnowledgeVersionStatus::Approved)throw new \DomainException('Only approved knowledge can be attached.');$existing=AgentVersionKnowledgeSource::query()->where('agent_version_id',$version->id)->where('knowledge_source_id',$source->id)->lockForUpdate()->first();if($existing&&(int)$existing->knowledge_source_version_id===(int)$kv->id)return$existing;if($existing)$existing->detachAuthorized($a);$link=new AgentVersionKnowledgeSource();$link->agent_version_id=$version->id;$link->knowledge_source_id=$source->id;$link->knowledge_source_version_id=$kv->id;$link->attached_by_user_id=$a->actorUserId;$link->save();return$link;});}catch(QueryException$e){if(!KnowledgeConstraintClassifier::isAttachmentSourceCollision($e))throw$e;$current=AgentVersionKnowledgeSource::query()->where('agent_version_id',AgentVersion::query()->where('agent_id',$agent->id)->where('status',AgentVersionStatus::Draft->value)->value('id'))->where('knowledge_source_id',$knowledge->knowledge_source_id)->first();if($current&&(int)$current->knowledge_source_version_id===(int)$knowledge->id)return$current;throw new KnowledgeAttachmentConflictException('A concurrent knowledge attachment selected another version.',0,$e);}}}
